import assert from 'node:assert';
import test from 'node:test';
import { createState, step } from './neon.js';

test('Ball bounces off top of brick', () => {
  const state = createState(1);
  const brick = { x: 0, y: 20, w: 100, h: 20, alive: true };
  state.bricks = [brick];
  state.ball = { x: 50, y: 19, r: 7, vx: 0, vy: 100 }; // Moving DOWN

  step(state, 0.01);

  assert.ok(state.ball.vy < 0, 'Ball should bounce UP');
});

test('Ball bounces off side of brick', () => {
  const state = createState(1);
  const brick = { x: 20, y: 20, w: 20, h: 20, alive: true };
  state.bricks = [brick];
  state.ball = { x: 19, y: 30, r: 7, vx: 100, vy: 0 }; // Moving RIGHT

  step(state, 0.01);

  assert.ok(state.ball.vx < 0, 'Ball should bounce LEFT');
});

test('Ball is pushed out of brick after bounce', () => {
  const state = createState(1);
  const brick = { x: 0, y: 20, w: 100, h: 20, alive: true };
  state.bricks = [brick];
  state.ball = { x: 50, y: 22, r: 7, vx: 0, vy: 100 }; // Deeply inside

  step(state, 0.01);

  assert.ok(state.ball.y + state.ball.r <= brick.y || state.ball.y - state.ball.r >= brick.y + brick.h, 'Ball should not be inside brick');
});

test('High speed ball does not tunnel through brick', () => {
  const state = createState(3); 
  const brick = { x: 0, y: 0, w: 100, h: 20, alive: true };
  state.bricks = [brick];

  state.ball = { x: 50, y: -10, r: 7, vx: 0, vy: 1000 }; 

  step(state, 0.05); // 50px move

  assert.ok(state.ball.vy < 0 || !brick.alive, 'Ball should have collided with brick');
});
